package com.primehr.rsp.evaluation.api;
import com.primehr.rsp.evaluation.domain.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.*;import java.time.*;import java.util.*;
public final class EvaluationExecutionDtos{private EvaluationExecutionDtos(){}
 public record Transition(@NotNull Long recordVersion,@Size(max=2000)String reason){}
 public record SessionInput(@NotBlank String stageId,@NotNull Instant startsAt,@NotNull Instant endsAt,@NotBlank @Size(max=80)String timeZone,@NotNull EvaluationSession.DeliveryMode deliveryMode,@Size(max=500)String venue,@Size(max=2000)String instructions,@Positive Integer capacity,@NotBlank @Size(max=100)String responsibleEmployeeNo,@NotEmpty List<@NotBlank String>candidateIds,Long recordVersion,@Size(max=2000)String changeReason){}
 public record AttendanceInput(@NotNull Long recordVersion,@NotNull EvaluationSessionCandidate.Attendance status,@Size(max=1000)String reason){}
 public record SessionCandidateResponse(String id,String candidateId,String invitationStatus,String attendanceStatus,long recordVersion){}
 public record SessionResponse(String id,String proceedingId,String stageId,int sessionRevision,String status,Instant startsAt,Instant endsAt,String timeZone,String deliveryMode,String venue,String instructions,Integer capacity,String responsibleEmployeeNo,String changeReason,long recordVersion,List<SessionCandidateResponse>candidates){}
 public record AssignmentInput(String stageId,String candidateId,@NotBlank @Size(max=100)String employeeNo,@NotNull EvaluationAssignment.Role role,@Size(max=100)String alternateForEmployeeNo){}
 public record Assignments(@NotNull Long proceedingRecordVersion,@NotEmpty List<@Valid AssignmentInput>assignments,@Size(max=1000)String replacementReason){}
 public record AssignmentResponse(String id,String stageId,String candidateId,String employeeNo,String role,boolean active,String alternateForEmployeeNo,long recordVersion){}
 public record ConflictInput(@NotNull Long proceedingRecordVersion,@NotBlank String candidateId,@NotNull ConflictDeclaration.Outcome outcome,@NotBlank @Size(max=2000)String declaration){}
 public record ResolveConflict(@NotNull Long recordVersion,@NotNull ConflictDeclaration.Resolution resolution,@NotBlank @Size(max=2000)String reason){}
 public record ConflictResponse(String id,String proceedingId,String candidateId,String employeeNo,String outcome,String resolution,String declaration,long recordVersion){}
 public record StageResultInput(@NotBlank String sessionId,@NotBlank String candidateId,@NotBlank String stageId,BigDecimal rawScore,BigDecimal maximumScore,StageResult.GateOutcome gateOutcome,@Size(max=2000)String remarks,Long recordVersion){}
 public record StageResultResponse(String id,String proceedingId,String sessionId,String candidateId,String stageId,int revision,String status,BigDecimal rawScore,BigDecimal maximumScore,BigDecimal normalizedScore,String gateOutcome,String remarks,String recordedBy,String submittedBy,String validatedBy,String returnReason,long recordVersion){}
 public record RatingItemInput(@NotBlank String criterionId,@NotNull @DecimalMin("0")BigDecimal rawScore,@NotNull @DecimalMin(value="0",inclusive=false)BigDecimal maximumScore,@Size(max=2000)String remarks){}
 public record RatingInput(@NotBlank String candidateId,@NotBlank String stageId,@NotEmpty List<@Valid RatingItemInput>items,@Size(max=2000)String overallRemarks,Long recordVersion){}
 public record RatingItemResponse(String criterionId,BigDecimal rawScore,BigDecimal maximumScore,BigDecimal normalizedScore,BigDecimal weightedScore,String remarks){}
 public record RatingResponse(String id,String proceedingId,String candidateId,String stageId,String raterEmployeeNo,int revision,String status,BigDecimal normalizedScore,String overallRemarks,String returnReason,long recordVersion,List<RatingItemResponse>items){}
 public record ReferenceInput(@NotBlank String candidateId,@NotBlank String stageId,@NotBlank @Size(max=80)String checkType,@NotBlank @Size(max=100)String sourceCategory,@NotBlank @Size(max=500)String lawfulBasisReference,Long recordVersion){}
 public record CompleteReference(@NotNull Long recordVersion,@NotNull ReferenceCheck.Outcome outcome,@Size(max=1000)String applicantSafeText,@Size(max=4000)String confidentialNotes){}
 public record ReferenceResponse(String id,String proceedingId,String candidateId,String stageId,String checkType,String sourceCategory,String lawfulBasisReference,String checkerEmployeeNo,String outcome,String status,String applicantSafeText,String confidentialNotes,String validatedBy,long recordVersion){}
 public record MeetingInput(@NotNull Instant scheduledAt,@NotBlank @Size(max=80)String timeZone,@Size(max=500)String venue,@NotBlank @Size(max=4000)String agenda,@Min(1)int quorumRequired,@Size(max=32000)String minutes,Long recordVersion){}
 public record MeetingAttendance(@NotBlank @Size(max=100)String employeeNo,@NotNull HrmpsbAttendance.Status status,@Size(max=1000)String remarks){}
 public record ResolutionInput(@NotBlank String candidateId,@NotNull HrmpsbResolution.Recommendation recommendation,@NotBlank @Size(max=3000)String reason,@NotNull HrmpsbResolution.Method method,@PositiveOrZero Integer votesFor,@PositiveOrZero Integer votesAgainst,@PositiveOrZero Integer abstentions){}
 public record MeetingResponse(String id,String proceedingId,int revision,String status,Instant scheduledAt,String timeZone,String venue,String agenda,String minutes,int quorumRequired,String finalizedBy,Instant finalizedAt,long recordVersion){}
 public record ComparativeItemResponse(String candidateId,BigDecimal totalScore,int rankNumber,int tieGroup,String stageBreakdown,boolean excluded,String exclusionReason){}
 public record ComparativeResponse(String id,String proceedingId,int revision,String status,String policyId,int policyDefinitionVersion,String policyFingerprint,String calculationFingerprint,String generatedBy,Instant generatedAt,String finalizedBy,Instant finalizedAt,long recordVersion,List<ComparativeItemResponse>items){}
 public record EvidenceResponse(String id,String proceedingId,String candidateId,String ownerType,String ownerId,String classification,String filename,String mediaType,long byteSize,String checksum,String retentionTag,long recordVersion){}
 public record ApplicantSchedule(String sessionId,String stageName,Instant startsAt,Instant endsAt,String timeZone,String deliveryMode,String venue,String invitationStatus,String attendanceStatus){}
 public record ApplicantEvaluationStatus(String applicationId,String progress,List<ApplicantSchedule>schedules){}
 public record MeetingAttendanceResponse(String id,String meetingId,String employeeNo,String memberRole,String status,boolean votingEligible,long recordVersion){}
 public record ResolutionResponse(String id,String meetingId,String candidateId,String recommendation,String reason,String method,Integer votesFor,Integer votesAgainst,Integer abstentions,long recordVersion){}
 public record ExecutionOverview(String proceedingId,long proceedingRecordVersion,List<SessionResponse>sessions,List<AssignmentResponse>assignments,List<ConflictResponse>conflicts,List<StageResultResponse>results,List<RatingResponse>ratings,List<ReferenceResponse>referenceChecks,List<MeetingResponse>meetings,List<MeetingAttendanceResponse>meetingAttendance,List<ResolutionResponse>resolutions,List<ComparativeResponse>comparativeEvaluations,List<EvidenceResponse>evidence){}
}
